// Modo: Run Once for All Items.
// Apunta como avisado solo lo que Telegram ha aceptado. Si el envio falla no
// se apunta, y te vuelve a avisar dentro de quince minutos: es el fallo que
// quieres. El contrario, apuntar y no avisar, te deja sin enterarte.

const estado = $getWorkflowStaticData('global');
estado.avisados = estado.avisados ?? {};
const pedidos = $('Buscar eventos que tocan').all();

$input.all().forEach((item, i) => {
  // El nodo HTTP pisa el json con la respuesta de Telegram: la clave hay que
  // ir a buscarla al item que lo origino.
  const clave = pedidos[item.pairedItem?.item ?? i]?.json?.clave;
  if (clave && item.json?.ok === true) estado.avisados[clave] = Date.now();
});

return [];

function eventosDeGoogle(resp) {
  // La API devuelve un solo item con la lista en "items". Si la peticion falla,
  // el nodo HTTP deja pasar el error como dato y aqui se convierte en motivo:
  // "no he podido leer" no es lo mismo que "no hay nada", y confundirlos es
  // justo el fallo del que no te enteras.
  if (!resp || resp.error || !Array.isArray(resp.items)) {
    const e = resp?.error;
    const motivo = String(e?.message ?? e?.description ?? e ?? 'Google no ha devuelto eventos');
    return { error: motivo.slice(0, 200), eventos: [] };
  }
  const eventos = [];
  for (const ev of resp.items) {
    if (ev.status === 'cancelled') continue;
    // Una invitacion que rechazaste sigue en tu calendario, pero no vas.
    const yo = (ev.attendees ?? []).find((a) => a.self);
    if (yo && yo.responseStatus === 'declined') continue;
    const todoElDia = !ev.start?.dateTime;
    const d = todoElDia
      ? DateTime.fromISO(String(ev.start?.date ?? ''), { zone: 'Europe/Madrid' })
      : DateTime.fromISO(ev.start.dateTime).setZone('Europe/Madrid');
    if (!d.isValid) continue;
    eventos.push({
      id: ev.id,
      titulo: String(ev.summary ?? '').trim() || '(sin título)',
      descripcion: String(ev.description ?? ''),
      d,
      todoElDia,
    });
  }
  eventos.sort((a, b) => a.d.toMillis() - b.d.toMillis());
  return { error: null, eventos };
}

function chatPermitido() {
  // En un chat privado el chat_id es tu propio user id, asi que no hace falta
  // guardarlo en ningun sitio: ya esta en el entorno desde la fase 1.
  const c = $env.TELEGRAM_ALLOWED_USER_ID;
  if (!c) throw new Error('TELEGRAM_ALLOWED_USER_ID no esta definido en el contenedor de n8n');
  return Number(c);
}

// Modo: Run Once for All Items.
// Saca un item por evento de tu Google Calendar que toque avisar ahora.
//
// Lo ya avisado se apunta en el staticData de este workflow, no en el evento:
// asi no se toca nada de tu calendario. La clave es el id del evento mas su
// hora, de modo que si lo mueves te vuelve a avisar a la hora nueva. Ojo, el
// staticData solo se guarda en ejecuciones de produccion: probandolo a mano
// avisaria cada vez.

// Cuanta antelacion quieres. Con el Schedule cada 15 minutos, el aviso te
// llega entre 45 y 60 minutos antes. La peticion de "Leer el calendario" usa
// esta misma ventana: si cambias una, cambia la otra.
const ANTELACION_MIN = 60;
// Ventana hacia atras, para los que se escaparon con el bot parado. Sin esto,
// un corte de una hora te deja sin avisar y sin enterarte.
const RETRASO_MAX_MIN = 120;
// Si Google no responde, te lo dice, pero no cada quince minutos.
const HORAS_ENTRE_ALERTAS = 6;

const chat = chatPermitido();
const estado = $getWorkflowStaticData('global');
estado.avisados = estado.avisados ?? {};

const ahora = DateTime.now().setZone('Europe/Madrid');
const desde = ahora.minus({ minutes: RETRASO_MAX_MIN });
const hasta = ahora.plus({ minutes: ANTELACION_MIN });

const { error, eventos } = eventosDeGoogle($input.first()?.json);

if (error) {
  // Un calendario que no se puede leer es un bot que no avisa, y eso no se
  // nota hasta que te pierdes algo. Mejor un mensaje cada seis horas.
  if (Date.now() - (estado.ultimaAlerta ?? 0) < HORAS_ENTRE_ALERTAS * 3600 * 1000) return [];
  estado.ultimaAlerta = Date.now();
  return [{ json: { chat_id: chat, clave: null, texto: '⚠️ No puedo leer tu calendario ' +
    'de Google, así que no te estoy avisando de nada.\nMotivo: ' + error } }];
}
estado.ultimaAlerta = 0;

// Las marcas de hace mas de tres dias ya no pueden volver a la ventana.
for (const [clave, cuando] of Object.entries(estado.avisados)) {
  if (Date.now() - cuando > 3 * 24 * 3600 * 1000) delete estado.avisados[clave];
}

const salida = [];

for (const e of eventos) {
  // Un evento de todo el dia no tiene hora a la que avisar: sale en el
  // resumen de las 8:00 y ya.
  if (e.todoElDia) continue;
  if (e.d < desde || e.d > hasta) continue;
  const clave = e.id + '|' + e.d.toISO();
  if (estado.avisados[clave]) continue;

  const faltan = Math.round(e.d.diff(ahora, 'minutes').minutes);
  const hora = e.d.toFormat('HH:mm');

  const texto = faltan >= 0
    ? '⏰ Dentro de ' + faltan + ' min: ' + e.titulo + '\nA las ' + hora + '.'
    : '⏰ Se te ha pasado hace ' + Math.abs(faltan) + ' min: ' + e.titulo +
      '\nEra a las ' + hora + '.';

  salida.push({ json: { chat_id: chat, clave, titulo: e.titulo, texto } });
}

return salida;
